1	import React from "react";
2	import cloneDeep from "lodash.clonedeep";
3	import clamp from "lodash.clamp";
4	import buffer from "buffer";
5	import get from "lodash.get";
6	import {unset} from "lodash";
7	import {arrayMoveMutable} from "array-move";
8	import hash from "string-hash";
9	import { PMTiles } from "pmtiles";
10	import {type Map, type LayerSpecification, type StyleSpecification, type ValidationError, type SourceSpecification} from "maplibre-gl";
11	import {validateStyleMin} from "@maplibre/maplibre-gl-style-spec";
12	import latest from "@maplibre/maplibre-gl-style-spec/dist/latest.json";
13	
14	import MapMaplibreGl from "./MapMaplibreGl";
15	import MapOpenLayers from "./MapOpenLayers";
16	import CodeEditor from "./CodeEditor";
17	import LayerList from "./LayerList";
18	import LayerEditor from "./LayerEditor";
19	import AppToolbar, { type MapState } from "./AppToolbar";
20	import AppLayout from "./AppLayout";
21	import MessagePanel from "./AppMessagePanel";
22	
23	import ModalSettings from "./modals/ModalSettings";
24	import ModalExport from "./modals/ModalExport";
25	import ModalSources from "./modals/ModalSources";
26	import ModalOpen from "./modals/ModalOpen";
27	import ModalShortcuts from "./modals/ModalShortcuts";
28	import ModalDebug from "./modals/ModalDebug";
29	import ModalGlobalState from "./modals/ModalGlobalState";
30	
31	import {downloadGlyphsMetadata, downloadSpriteMetadata} from "../libs/metadata";
32	import style from "../libs/style";
33	import { undoMessages, redoMessages } from "../libs/diffmessage";
34	import { createStyleStore, type IStyleStore } from "../libs/store/style-store-factory";
35	import { RevisionStore } from "../libs/revisions";
36	import LayerWatcher from "../libs/layerwatcher";
37	import tokens from "../config/tokens.json";
38	import isEqual from "lodash.isequal";
39	import { type MapOptions } from "maplibre-gl";
40	import { type MappedError, type OnStyleChangedOpts, type StyleSpecificationWithId } from "../libs/definitions";
41	
42	// Buffer must be defined globally for @maplibre/maplibre-gl-style-spec validate() function to succeed.
43	window.Buffer = buffer.Buffer;
44	
45	function setFetchAccessToken(url: string, mapStyle: StyleSpecification) {
46	  const matchesTilehosting = url.match(/\.tilehosting\.com/);
47	  const matchesMaptiler = url.match(/\.maptiler\.com/);
48	  const matchesThunderforest = url.match(/\.thunderforest\.com/);
49	  const matchesLocationIQ = url.match(/\.locationiq\.com/);
50	  if (matchesTilehosting || matchesMaptiler) {
51	    const accessToken = style.getAccessToken("openmaptiles", mapStyle, {allowFallback: true});
52	    if (accessToken) {
53	      return url.replace("{key}", accessToken);
54	    }
55	  }
56	  else if (matchesThunderforest) {
57	    const accessToken = style.getAccessToken("thunderforest", mapStyle, {allowFallback: true});
58	    if (accessToken) {
59	      return url.replace("{key}", accessToken);
60	    }
61	  }
62	  else if (matchesLocationIQ) {
63	    const accessToken = style.getAccessToken("locationiq", mapStyle, {allowFallback: true});
64	    if (accessToken) {
65	      return url.replace("{key}", accessToken);
66	    }
67	  }
68	  else {
69	    return url;
70	  }
71	}
72	
73	function updateRootSpec(spec: any, fieldName: string, newValues: any) {
74	  return {
75	    ...spec,
76	    $root: {
77	      ...spec.$root,
78	      [fieldName]: {
79	        ...spec.$root[fieldName],
80	        values: newValues
81	      }
82	    }
83	  };
84	}
85	
86	type AppState = {
87	  errors: MappedError[],
88	  infos: string[],
89	  mapStyle: StyleSpecificationWithId,
90	  dirtyMapStyle?: StyleSpecification,
91	  selectedLayerIndex: number,
92	  selectedLayerOriginalId?: string,
93	  sources: {[key: string]: SourceSpecification & {layers: string[]} },
94	  vectorLayers: {},
95	  spec: any,
96	  mapView: {
97	    zoom: number,
98	    center: {
99	      lng: number,
100	      lat: number,
101	    },
102	    _from: "map" | "app"
103	  },
104	  maplibreGlDebugOptions: Partial<MapOptions> & {
105	    showTileBoundaries: boolean,
106	    showCollisionBoxes: boolean,
107	    showOverdrawInspector: boolean,
108	  },
109	  openlayersDebugOptions: {
110	    debugToolbox: boolean,
111	  },
112	  mapState: MapState
113	  isOpen: {
114	    settings: boolean
115	    sources: boolean
116	    open: boolean
117	    shortcuts: boolean
118	    export: boolean
119	    debug: boolean
120	    globalState: boolean
121	    codeEditor: boolean
122	  }
123	  fileHandle: FileSystemFileHandle | null
124	};
125	
126	export default class App extends React.Component<any, AppState> {
127	  revisionStore: RevisionStore;
128	  styleStore: IStyleStore | null = null;
129	  layerWatcher: LayerWatcher;
130	
131	  constructor(props: any) {
132	    super(props);
133	
134	    this.revisionStore = new RevisionStore();
135	    this.configureKeyboardShortcuts();
136	
137	    this.state = {
138	      errors: [],
139	      infos: [],
140	      mapStyle: style.emptyStyle,
141	      selectedLayerIndex: 0,
142	      sources: {},
143	      vectorLayers: {},
144	      mapState: "map",
145	      spec: latest,
146	      mapView: {
147	        zoom: 0,
148	        center: {
149	          lng: 0,
150	          lat: 0,
151	        },
152	        _from: "app"
153	      },
154	      isOpen: {
155	        settings: false,
156	        sources: false,
157	        open: false,
158	        shortcuts: false,
159	        export: false,
160	        debug: false,
161	        globalState: false,
162	        codeEditor: false
163	      },
164	      maplibreGlDebugOptions: {
165	        showTileBoundaries: false,
166	        showCollisionBoxes: false,
167	        showOverdrawInspector: false,
168	      },
169	      openlayersDebugOptions: {
170	        debugToolbox: false,
171	      },
172	      fileHandle: null,
173	    };
174	
175	    this.layerWatcher = new LayerWatcher({
176	      onVectorLayersChange: v => this.setState({ vectorLayers: v })
177	    });
178	  }
179	
180	  configureKeyboardShortcuts = () => {
181	    const shortcuts = [
182	      {
183	        key: "?",
184	        handler: () => {
185	          this.toggleModal("shortcuts");
186	        }
187	      },
188	      {
189	        key: "o",
190	        handler: () => {
191	          this.toggleModal("open");
192	        }
193	      },
194	      {
195	        key: "e",
196	        handler: () => {
197	          this.toggleModal("export");
198	        }
199	      },
200	      {
201	        key: "d",
202	        handler: () => {
203	          this.toggleModal("sources");
204	        }
205	      },
206	      {
207	        key: "s",
208	        handler: () => {
209	          this.toggleModal("settings");
210	        }
211	      },
212	      {
213	        key: "g",
214	        handler: () => {
215	          this.toggleModal("globalState");
216	        }
217	      },
218	      {
219	        key: "i",
220	        handler: () => {
221	          this.setMapState(
222	            this.state.mapState === "map" ? "inspect" : "map"
223	          );
224	        }
225	      },
226	      {
227	        key: "m",
228	        handler: () => {
229	          (document.querySelector(".maplibregl-canvas") as HTMLCanvasElement).focus();
230	        }
231	      },
232	      {
233	        key: "!",
234	        handler: () => {
235	          this.toggleModal("debug");
236	        }
237	      },
238	    ];
239	
240	    document.body.addEventListener("keyup", (e) => {
241	      if(e.key === "Escape") {
242	        (e.target as HTMLElement).blur();
243	        document.body.focus();
244	      }
245	      else if(this.state.isOpen.shortcuts || document.activeElement === document.body) {
246	        const shortcut = shortcuts.find((shortcut) => {
247	          return (shortcut.key === e.key);
248	        });
249	
250	        if(shortcut) {
251	          this.setModal("shortcuts", false);
252	          shortcut.handler();
253	        }
254	      }
255	    });
256	  };
257	
258	  handleKeyPress = (e: KeyboardEvent) => {
259	    if(navigator.platform.toUpperCase().indexOf("MAC") >= 0) {
260	      if(e.metaKey && e.shiftKey && e.keyCode === 90) {
261	        e.preventDefault();
262	        this.onRedo();
263	      }
264	      else if(e.metaKey && e.keyCode === 90) {
265	        e.preventDefault();
266	        this.onUndo();
267	      }
268	    }
269	    else {
270	      if(e.ctrlKey && e.keyCode === 90) {
271	        e.preventDefault();
272	        this.onUndo();
273	      }
274	      else if(e.ctrlKey && e.keyCode === 89) {
275	        e.preventDefault();
276	        this.onRedo();
277	      }
278	    }
279	  };
280	
281	  async componentDidMount() {
282	    this.styleStore = await createStyleStore((mapStyle, opts) => this.onStyleChanged(mapStyle, opts));
283	    window.addEventListener("keydown", this.handleKeyPress);
284	  }
285	
286	  componentWillUnmount() {
287	    window.removeEventListener("keydown", this.handleKeyPress);
288	  }
289	
290	  saveStyle(snapshotStyle: StyleSpecificationWithId) {
291	    this.styleStore?.save(snapshotStyle);
292	  }
293	
294	  updateFonts(urlTemplate: string) {
295	    const metadata: {[key: string]: string} = this.state.mapStyle.metadata || {} as any;
296	    const accessToken = metadata["maputnik:openmaptiles_access_token"] || tokens.openmaptiles;
297	
298	    const glyphUrl = (typeof urlTemplate === "string")? urlTemplate.replace("{key}", accessToken): urlTemplate;
299	    downloadGlyphsMetadata(glyphUrl).then(fonts => {
300	      this.setState({ spec: updateRootSpec(this.state.spec, "glyphs", fonts)});
301	    });
302	  }
303	
304	  updateIcons(baseUrl: string) {
305	    downloadSpriteMetadata(baseUrl).then(icons => {
306	      this.setState({ spec: updateRootSpec(this.state.spec, "sprite", icons)});
307	    });
308	  }
309	
310	  onChangeMetadataProperty = (property: string, value: any) => {
311	    // If we're changing renderer reset the map state.
312	    if (
313	      property === "maputnik:renderer" &&
314	      value !== get(this.state.mapStyle, ["metadata", "maputnik:renderer"], "mlgljs")
315	    ) {
316	      this.setState({
317	        mapState: "map"
318	      });
319	    }
320	
321	    const changedStyle = {
322	      ...this.state.mapStyle,
323	      metadata: {
324	        ...(this.state.mapStyle as any).metadata,
325	        [property]: value
326	      }
327	    };
328	
329	    this.onStyleChanged(changedStyle);
330	  };
331	
332	  onStyleChanged = (newStyle: StyleSpecificationWithId, opts: OnStyleChangedOpts={}): void => {
333	    opts = {
334	      save: true,
335	      addRevision: true,
336	      initialLoad: false,
337	      ...opts,
338	    };
339	
340	
341	    // Detect empty style
342	    const oldStyle = this.state.mapStyle;
343	    const isEmptySources = !oldStyle.sources || Object.keys(oldStyle.sources).length === 0;
344	    const isEmptyLayers = !oldStyle.layers || oldStyle.layers.length === 0;
345	    const isEmptyStyle = isEmptySources && isEmptyLayers;
346	
347	    // For the style object, find the urls that has "{key}" and insert the correct API keys
348	    // Without this, going from e.g. MapTiler to OpenLayers and back will lose the maptlier key.
349	
350	    if (newStyle.glyphs && typeof newStyle.glyphs === "string") {
351	      newStyle.glyphs = setFetchAccessToken(newStyle.glyphs, newStyle);
352	    }
353	
354	    if (newStyle.sprite && typeof newStyle.sprite === "string") {
355	      newStyle.sprite = setFetchAccessToken(newStyle.sprite, newStyle);
356	    }
357	
358	    for (const [_sourceId, source] of Object.entries(newStyle.sources)) {
359	      if (source && "url" in source && typeof source.url === "string") {
360	        source.url = setFetchAccessToken(source.url, newStyle);
361	      }
362	    }
363	
364	
365	    if (opts.initialLoad) {
366	      this.getInitialStateFromUrl(newStyle);
367	    }
368	
369	    const errors: ValidationError[] = validateStyleMin(newStyle) || [];
370	    // The validate function doesn't give us errors for duplicate error with
371	    // empty string for layer.id, manually deal with that here.
372	    const layerErrors: (Error | ValidationError)[] = [];
373	    if (newStyle && newStyle.layers) {
374	      const foundLayers = new global.Map();
375	      newStyle.layers.forEach((layer, index) => {
376	        if (layer.id === "" && foundLayers.has(layer.id)) {
377	          const error = new Error(
378	            `layers[${index}]: duplicate layer id [empty_string], previously used`
379	          );
380	          layerErrors.push(error);
381	        }
382	        foundLayers.set(layer.id, true);
383	      });
384	    }
385	
386	    const mappedErrors: MappedError[] = layerErrors.concat(errors).map(error => {
387	      // Special case: Duplicate layer id
388	      const dupMatch = error.message.match(/layers\[(\d+)\]: (duplicate layer id "?(.*)"?, previously used)/);
389	      if (dupMatch) {
390	        const [, index, message] = dupMatch;
391	        return {
392	          message: error.message,
393	          parsed: {
394	            type: "layer",
395	            data: {
396	              index: parseInt(index, 10),
397	              key: "id",
398	              message,
399	            }
400	          }
401	        };
402	      }
403	
404	      // Special case: Invalid source
405	      const invalidSourceMatch = error.message.match(/layers\[(\d+)\]: (source "(?:.*)" not found)/);
406	      if (invalidSourceMatch) {
407	        const [, index, message] = invalidSourceMatch;
408	        return {
409	          message: error.message,
410	          parsed: {
411	            type: "layer",
412	            data: {
413	              index: parseInt(index, 10),
414	              key: "source",
415	              message,
416	            }
417	          }
418	        };
419	      }
420	
421	      const layerMatch = error.message.match(/layers\[(\d+)\]\.(?:(\S+)\.)?(\S+): (.*)/);
422	      if (layerMatch) {
423	        const [, index, group, property, message] = layerMatch;
424	        const key = (group && property) ? [group, property].join(".") : property;
425	        return {
426	          message: error.message,
427	          parsed: {
428	            type: "layer",
429	            data: {
430	              index: parseInt(index, 10),
431	              key,
432	              message
433	            }
434	          }
435	        };
436	      }
437	      else {
438	        return {
439	          message: error.message,
440	        };
441	      }
442	    });
443	
444	    let dirtyMapStyle: StyleSpecification | undefined = undefined;
445	    if (errors.length > 0) {
446	      dirtyMapStyle = cloneDeep(newStyle);
447	
448	      for (const error of errors) {
449	        const {message} = error;
450	        if (message) {
451	          try {
452	            const objPath = message.split(":")[0];
453	            // Errors can be deeply nested for example 'layers[0].filter[1][1][0]' we only care upto the property 'layers[0].filter'
454	            const unsetPath = objPath.match(/^\S+?\[\d+\]\.[^[]+/)![0];
455	            unset(dirtyMapStyle, unsetPath);
456	          }
457	          catch (err) {
458	            console.warn(message + " " + err);
459	          }
460	        }
461	      }
462	    }
463	
464	    if(newStyle.glyphs !== this.state.mapStyle.glyphs) {
465	      this.updateFonts(newStyle.glyphs as string);
466	    }
467	    if(newStyle.sprite !== this.state.mapStyle.sprite) {
468	      this.updateIcons(newStyle.sprite as string);
469	    }
470	
471	    if (opts.addRevision) {
472	      this.revisionStore.addRevision(newStyle);
473	    }
474	    if (opts.save) {
475	      this.saveStyle(newStyle);
476	    }
477	
478	    const zoom = newStyle?.zoom;
479	    const center = newStyle?.center;
480	
481	    this.setState({
482	      mapStyle: newStyle,
483	      dirtyMapStyle: dirtyMapStyle,
484	      mapView: isEmptyStyle && zoom && center ? {
485	        zoom: zoom,
486	        center: {
487	          lng: center[0],
488	          lat: center[1],
489	        },
490	        _from: "app"
491	      } : this.state.mapView,
492	      errors: mappedErrors,
493	    }, () => {
494	      this.fetchSources();
495	      this.setStateInUrl();
496	    });
497	  };
498	
499	  onUndo = () => {
500	    const activeStyle = this.revisionStore.undo();
501	
502	    const messages = undoMessages(this.state.mapStyle, activeStyle);
503	    this.onStyleChanged(activeStyle, {addRevision: false});
504	    this.setState({
505	      infos: messages,
506	    });
507	  };
508	
509	  onRedo = () => {
510	    const activeStyle = this.revisionStore.redo();
511	    const messages = redoMessages(this.state.mapStyle, activeStyle);
512	    this.onStyleChanged(activeStyle, {addRevision: false});
513	    this.setState({
514	      infos: messages,
515	    });
516	  };
517	
518	  onMoveLayer = (move: {oldIndex: number; newIndex: number}) => {
519	    let { oldIndex, newIndex } = move;
520	    let layers = this.state.mapStyle.layers;
521	    oldIndex = clamp(oldIndex, 0, layers.length-1);
522	    newIndex = clamp(newIndex, 0, layers.length-1);
523	    if(oldIndex === newIndex) return;
524	
525	    if (oldIndex === this.state.selectedLayerIndex) {
526	      this.setState({
527	        selectedLayerIndex: newIndex
528	      });
529	    }
530	
531	    layers = layers.slice(0);
532	    arrayMoveMutable(layers, oldIndex, newIndex);
533	    this.onLayersChange(layers);
534	  };
535	
536	  onLayersChange = (changedLayers: LayerSpecification[]) => {
537	    const changedStyle = {
538	      ...this.state.mapStyle,
539	      layers: changedLayers
540	    };
541	    this.onStyleChanged(changedStyle);
542	  };
543	
544	  onLayerDestroy = (index: number) => {
545	    const layers = this.state.mapStyle.layers;
546	    const remainingLayers = layers.slice(0);
547	    remainingLayers.splice(index, 1);
548	    this.onLayersChange(remainingLayers);
549	  };
550	
551	  onLayerCopy = (index: number) => {
552	    const layers = this.state.mapStyle.layers;
553	    const changedLayers = layers.slice(0);
554	
555	    const clonedLayer = cloneDeep(changedLayers[index]);
556	    clonedLayer.id = clonedLayer.id + "-copy";
557	    changedLayers.splice(index, 0, clonedLayer);
558	    this.onLayersChange(changedLayers);
559	  };
560	
561	  onLayerVisibilityToggle = (index: number) => {
562	    const layers = this.state.mapStyle.layers;
563	    const changedLayers = layers.slice(0);
564	
565	    const layer = { ...changedLayers[index] };
566	    const changedLayout = "layout" in layer ? {...layer.layout} : {};
567	    changedLayout.visibility = changedLayout.visibility === "none" ? "visible" : "none";
568	
569	    layer.layout = changedLayout;
570	    changedLayers[index] = layer;
571	    this.onLayersChange(changedLayers);
572	  };
573	
574	
575	  onLayerIdChange = (index: number, _oldId: string, newId: string) => {
576	    const changedLayers = this.state.mapStyle.layers.slice(0);
577	    changedLayers[index] = {
578	      ...changedLayers[index],
579	      id: newId
580	    };
581	
582	    this.onLayersChange(changedLayers);
583	  };
584	
585	  onLayerChanged = (index: number, layer: LayerSpecification) => {
586	    const changedLayers = this.state.mapStyle.layers.slice(0);
587	    changedLayers[index] = layer;
588	
589	    this.onLayersChange(changedLayers);
590	  };
591	
592	  setMapState = (newState: MapState) => {
593	    this.setState({
594	      mapState: newState
595	    }, this.setStateInUrl);
596	  };
597	
598	  setDefaultValues = (styleObj: StyleSpecificationWithId) => {
599	    const metadata: {[key: string]: string} = styleObj.metadata || {} as any;
600	    if(metadata["maputnik:renderer"] === undefined) {
601	      const changedStyle = {
602	        ...styleObj,
603	        metadata: {
604	          ...styleObj.metadata as any,
605	          "maputnik:renderer": "mlgljs"
606	        }
607	      };
608	      return changedStyle;
609	    } else {
610	      return styleObj;
611	    }
612	  };
613	
614	  openStyle = (styleObj: StyleSpecificationWithId, fileHandle: FileSystemFileHandle | null) => {
615	    this.setState({fileHandle: fileHandle});
616	    styleObj = this.setDefaultValues(styleObj);
617	    this.onStyleChanged(styleObj);
618	  };
619	
620	  async fetchSources() {
621	    const sourceList: {[key: string]: SourceSpecification & {layers: string[]}} = {};
622	    for(const key of Object.keys(this.state.mapStyle.sources)) {
623	      const source = this.state.mapStyle.sources[key];
624	      if(source.type !== "vector" || !("url" in source)) {
625	        sourceList[key] = this.state.sources[key] || {...this.state.mapStyle.sources[key]};
626	        if (sourceList[key].layers === undefined) {
627	          sourceList[key].layers = [];
628	        }
629	      } else {
630	        sourceList[key] = {
631	          type: source.type,
632	          layers: []
633	        };
634	
635	        let url = source.url;
636	
637	        try {
638	          url = setFetchAccessToken(url!, this.state.mapStyle);
639	        } catch(err) {
640	          console.warn("Failed to setFetchAccessToken: ", err);
641	        }
642	
643	        const setVectorLayers = (json:any) => {
644	          if(!Object.prototype.hasOwnProperty.call(json, "vector_layers")) {
645	            return;
646	          }
647	
648	          for(const layer of json.vector_layers) {
649	            sourceList[key].layers.push(layer.id);
650	          }
651	        };
652	
653	        try {
654	          if (url!.startsWith("pmtiles://")) {
655	            const json = await (new PMTiles(url!.substring(10))).getTileJson("");
656	            setVectorLayers(json);
657	          } else {
658	            const response = await fetch(url!, { mode: "cors" });
659	            const json = await response.json();
660	            setVectorLayers(json);
661	          }
662	        } catch(err) {
663	          console.error(`Failed to process source for url: '${url}', ${err}`);
664	        }
665	      }
666	    }
667	
668	    if(!isEqual(this.state.sources, sourceList)) {
669	      console.debug("Setting sources", sourceList);
670	      this.setState({
671	        sources: sourceList
672	      });
673	    }
674	  }
675	
676	  _getRenderer () {
677	    const metadata: {[key:string]: string} = this.state.mapStyle.metadata || {} as any;
678	    return metadata["maputnik:renderer"] || "mlgljs";
679	  }
680	
681	  onMapChange = (mapView: {
682	    zoom: number,
683	    center: {
684	      lng: number,
685	      lat: number,
686	    },
687	    _from: "map" | "app"
688	  }) => {
689	    this.setState({
690	      mapView,
691	    });
692	  };
693	
694	  mapRenderer() {
695	    const {mapStyle, dirtyMapStyle} = this.state;
696	
697	    const mapProps = {
698	      mapStyle: (dirtyMapStyle || mapStyle),
699	      mapView: this.state.mapView,
700	      replaceAccessTokens: (mapStyle: StyleSpecification) => {
701	        return style.replaceAccessTokens(mapStyle, {
702	          allowFallback: true
703	        });
704	      },
705	      onDataChange: (e: {map: Map}) => {
706	        this.layerWatcher.analyzeMap(e.map);
707	        this.fetchSources();
708	      },
709	    };
710	
711	    const renderer = this._getRenderer();
712	
713	    let mapElement;
714	
715	    // Check if OL code has been loaded?
716	    if(renderer === "ol") {
717	      mapElement = <MapOpenLayers
718	        {...mapProps}
719	        onChange={this.onMapChange}
720	        debugToolbox={this.state.openlayersDebugOptions.debugToolbox}
721	        onLayerSelect={(layerId) => this.onLayerSelect(+layerId)}
722	      />;
723	    } else {
724	
725	      mapElement = <MapMaplibreGl {...mapProps}
726	        onChange={this.onMapChange}
727	        options={this.state.maplibreGlDebugOptions}
728	        inspectModeEnabled={this.state.mapState === "inspect"}
729	        highlightedLayer={this.state.mapStyle.layers[this.state.selectedLayerIndex]}
730	        onLayerSelect={this.onLayerSelect} />;
731	    }
732	
733	    let filterName;
734	    if(this.state.mapState.match(/^filter-/)) {
735	      filterName = this.state.mapState.replace(/^filter-/, "");
736	    }
737	    const elementStyle: {filter?: string} = {};
738	    if (filterName) {
739	      elementStyle.filter = `url('#${filterName}')`;
740	    }
741	
742	    return <div style={elementStyle} className="maputnik-map__container" data-wd-key="maplibre:container">
743	      {mapElement}
744	    </div>;
745	  }
746	
747	  setStateInUrl = () => {
748	    const {mapState, mapStyle, isOpen} = this.state;
749	    const {selectedLayerIndex} = this.state;
750	    const url = new URL(location.href);
751	    const hashVal = hash(JSON.stringify(mapStyle));
752	    url.searchParams.set("layer", `${hashVal}~${selectedLayerIndex}`);
753	
754	    const openModals = Object.entries(isOpen)
755	      .map(([key, val]) => (val === true ? key : null))
756	      .filter(val => val !== null);
757	
758	    if (openModals.length > 0) {
759	      url.searchParams.set("modal", openModals.join(","));
760	    }
761	    else {
762	      url.searchParams.delete("modal");
763	    }
764	
765	    if (mapState === "map") {
766	      url.searchParams.delete("view");
767	    }
768	    else if (mapState === "inspect") {
769	      url.searchParams.set("view", "inspect");
770	    }
771	
772	    history.replaceState({selectedLayerIndex}, "Maputnik", url.href);
773	  };
774	
775	  getInitialStateFromUrl = (mapStyle: StyleSpecification) => {
776	    const url = new URL(location.href);
777	    const modalParam = url.searchParams.get("modal");
778	
779	    if (modalParam && modalParam !== "") {
780	      const modals = modalParam.split(",");
781	      const modalObj: {[key: string]: boolean} = {};
782	      modals.forEach(modalName => {
783	        modalObj[modalName] = true;
784	      });
785	
786	      this.setState({
787	        isOpen: {
788	          ...this.state.isOpen,
789	          ...modalObj,
790	        }
791	      });
792	    }
793	
794	    const view = url.searchParams.get("view");
795	    if (view && view !== "") {
796	      this.setMapState(view as MapState);
797	    }
798	
799	    const path = url.searchParams.get("layer");
800	    if (path) {
801	      try {
802	        const parts = path.split("~");
803	        const [hashVal, selectedLayerIndex] = [
804	          parts[0],
805	          parseInt(parts[1], 10),
806	        ];
807	
808	        let valid = true;
809	        if (hashVal !== "-") {
810	          const currentHashVal = hash(JSON.stringify(mapStyle));
811	          if (currentHashVal !== parseInt(hashVal, 10)) {
812	            valid = false;
813	          }
814	        }
815	        if (valid) {
816	          this.setState({
817	            selectedLayerIndex,
818	            selectedLayerOriginalId: mapStyle.layers[selectedLayerIndex].id,
819	          });
820	        }
821	      }
822	      catch (err) {
823	        console.warn(err);
824	      }
825	    }
826	  };
827	
828	  onLayerSelect = (index: number) => {
829	    this.setState({
830	      selectedLayerIndex: index,
831	      selectedLayerOriginalId: this.state.mapStyle.layers[index].id,
832	    }, this.setStateInUrl);
833	  };
834	
835	  setModal(modalName: keyof AppState["isOpen"], value: boolean) {
836	    this.setState({
837	      isOpen: {
838	        ...this.state.isOpen,
839	        [modalName]: value
840	      }
841	    }, this.setStateInUrl);
842	  }
843	
