845	    this.setModal(modalName, !this.state.isOpen[modalName]);
846	  }
847	
848	  onSetFileHandle = (fileHandle: FileSystemFileHandle | null) => {
849	    this.setState({ fileHandle });
850	  };
851	
852	  onChangeOpenlayersDebug = (key: keyof AppState["openlayersDebugOptions"], value: boolean) => {
853	    this.setState({
854	      openlayersDebugOptions: {
855	        ...this.state.openlayersDebugOptions,
856	        [key]: value,
857	      }
858	    });
859	  };
860	
861	  onChangeMaplibreGlDebug = (key: keyof AppState["maplibreGlDebugOptions"], value: any) => {
862	    this.setState({
863	      maplibreGlDebugOptions: {
864	        ...this.state.maplibreGlDebugOptions,
865	        [key]: value,
866	      }
867	    });
868	  };
869	
870	  render() {
871	    const layers = this.state.mapStyle.layers || [];
872	    const selectedLayer = layers.length > 0 ? layers[this.state.selectedLayerIndex] : undefined;
873	
874	    const toolbar = <AppToolbar
875	      renderer={this._getRenderer()}
876	      mapState={this.state.mapState}
877	      mapStyle={this.state.mapStyle}
878	      inspectModeEnabled={this.state.mapState === "inspect"}
879	      sources={this.state.sources}
880	      onStyleChanged={this.onStyleChanged}
881	      onStyleOpen={this.onStyleChanged}
882	      onSetMapState={this.setMapState}
