902	      errors={this.state.errors}
903	    />;
904	
905	    const layerEditor = selectedLayer ? <LayerEditor
906	      key={this.state.selectedLayerOriginalId}
907	      layer={selectedLayer}
908	      layerIndex={this.state.selectedLayerIndex}
909	      isFirstLayer={this.state.selectedLayerIndex < 1}
910	      isLastLayer={this.state.selectedLayerIndex === this.state.mapStyle.layers.length-1}
911	      sources={this.state.sources}
912	      vectorLayers={this.state.vectorLayers}
913	      spec={this.state.spec}
914	      onMoveLayer={this.onMoveLayer}
915	      onLayerChanged={this.onLayerChanged}
916	      onLayerDestroy={this.onLayerDestroy}
917	      onLayerCopy={this.onLayerCopy}
918	      onLayerVisibilityToggle={this.onLayerVisibilityToggle}
919	      onLayerIdChange={this.onLayerIdChange}
920	      errors={this.state.errors}
921	    /> : undefined;
922	
923	    const bottomPanel = (this.state.errors.length + this.state.infos.length) > 0 ? <MessagePanel
924	      currentLayer={selectedLayer}
925	      selectedLayerIndex={this.state.selectedLayerIndex}
926	      onLayerSelect={this.onLayerSelect}
