928	      errors={this.state.errors}
929	      infos={this.state.infos}
930	    /> : undefined;
931	
932	
933	    const modals = <div>
934	      <ModalDebug
935	        renderer={this._getRenderer()}
936	        maplibreGlDebugOptions={this.state.maplibreGlDebugOptions}
937	        openlayersDebugOptions={this.state.openlayersDebugOptions}
938	        onChangeMaplibreGlDebug={this.onChangeMaplibreGlDebug}
939	        onChangeOpenlayersDebug={this.onChangeOpenlayersDebug}
940	        isOpen={this.state.isOpen.debug}
941	        onOpenToggle={() => this.toggleModal("debug")}
942	        mapView={this.state.mapView}
