949	        mapStyle={this.state.mapStyle}
950	        onStyleChanged={this.onStyleChanged}
951	        onChangeMetadataProperty={this.onChangeMetadataProperty}
952	        isOpen={this.state.isOpen.settings}
953	        onOpenToggle={() => this.toggleModal("settings")}
954	      />
955	      <ModalExport
956	        mapStyle={this.state.mapStyle}
957	        onStyleChanged={this.onStyleChanged}
958	        isOpen={this.state.isOpen.export}
959	        onOpenToggle={() => this.toggleModal("export")}
960	        fileHandle={this.state.fileHandle}
961	        onSetFileHandle={this.onSetFileHandle}
962	      />
963	      <ModalOpen
964	        isOpen={this.state.isOpen.open}
965	        onStyleOpen={this.openStyle}
966	        onOpenToggle={() => this.toggleModal("open")}
967	        fileHandle={this.state.fileHandle}
968	      />
969	      <ModalSources
970	        mapStyle={this.state.mapStyle}
971	        onStyleChanged={this.onStyleChanged}
972	        isOpen={this.state.isOpen.sources}
973	        onOpenToggle={() => this.toggleModal("sources")}
