1	import React, { type DragEvent, type FormEvent } from "react";
2	import { MdFileUpload } from "react-icons/md";
3	import { MdAddCircleOutline } from "react-icons/md";
4	import { Trans, type WithTranslation, withTranslation } from "react-i18next";
5	
6	import ModalLoading from "./ModalLoading";
7	import Modal from "./Modal";
8	import InputButton from "../InputButton";
9	import InputUrl from "../InputUrl";
10	
11	import style from "../../libs/style";
12	import publicStyles from "../../config/styles.json";
13	
14	type PublicStyleProps = {
15	  url: string
16	  thumbnailUrl: string
17	  title: string
18	  onSelect(...args: unknown[]): unknown
19	};
20	
21	class PublicStyle extends React.Component<PublicStyleProps> {
22	  render() {
23	    return <div className="maputnik-public-style">
24	      <InputButton
25	        className="maputnik-public-style-button"
26	        aria-label={this.props.title}
27	        onClick={() => this.props.onSelect(this.props.url)}
28	      >
29	        <div className="maputnik-public-style-header">
30	          <div>{this.props.title}</div>
31	          <span className="maputnik-space" />
32	          <MdAddCircleOutline />
33	        </div>
34	        <div
35	          className="maputnik-public-style-thumbnail"
36	          style={{
37	            backgroundImage: `url(${this.props.thumbnailUrl})`
38	          }}
39	        ></div>
40	      </InputButton>
41	    </div>;
42	  }
43	}
44	
45	type ModalOpenInternalProps = {
46	  isOpen: boolean
47	  onOpenToggle(): void
48	  onStyleOpen(...args: unknown[]): unknown
49	  fileHandle: FileSystemFileHandle | null
50	} & WithTranslation;
51	
52	type ModalOpenState = {
53	  styleUrl: string
54	  isDragOver: boolean
55	  error?: string | null
56	  activeRequest?: any
57	  activeRequestUrl?: string | null
58	};
59	
60	class ModalOpenInternal extends React.Component<ModalOpenInternalProps, ModalOpenState> {
61	  private fileInputRef = React.createRef<HTMLInputElement>();
62	
63	  constructor(props: ModalOpenInternalProps) {
64	    super(props);
65	    this.state = {
66	      styleUrl: "",
67	      isDragOver: false,
68	    };
69	  }
70	
71	  clearError() {
72	    this.setState({
73	      error: null
74	    });
75	  }
76	
77	  onCancelActiveRequest(e: Event) {
78	    // Else the click propagates to the underlying modal
79	    if (e) e.stopPropagation();
80	
81	    if (this.state.activeRequest) {
82	      this.state.activeRequest.abort();
83	      this.setState({
84	        activeRequest: null,
85	        activeRequestUrl: null
86	      });
87	    }
88	  }
89	
90	  onStyleSelect = (styleUrl: string) => {
91	    this.clearError();
92	
93	    let canceled: boolean = false;
94	
95	    fetch(styleUrl, {
96	      mode: "cors",
97	      credentials: "same-origin"
98	    })
99	      .then(function (response) {
100	        return response.json();
101	      })
102	      .then((body) => {
103	        if (canceled) {
104	          return;
105	        }
106	
107	        this.setState({
108	          activeRequest: null,
109	          activeRequestUrl: null
110	        });
111	
112	        const mapStyle = style.ensureStyleValidity(body);
113	        console.log("Loaded style ", mapStyle.id);
114	        this.props.onStyleOpen(mapStyle);
115	        this.onOpenToggle();
116	      })
117	      .catch((err) => {
118	        this.setState({
119	          error: `Failed to load: '${styleUrl}'`,
120	          activeRequest: null,
121	          activeRequestUrl: null
122	        });
123	        console.error(err);
124	        console.warn("Could not open the style URL", styleUrl);
125	      });
126	
127	    this.setState({
128	      activeRequest: {
129	        abort: function () {
130	          canceled = true;
131	        }
132	      },
133	      activeRequestUrl: styleUrl
134	    });
135	  };
136	
137	  onSubmitUrl = (e: FormEvent<HTMLFormElement>) => {
138	    e.preventDefault();
139	    this.onStyleSelect(this.state.styleUrl);
140	  };
141	
142	  onOpenFile = async () => {
143	    this.clearError();
144	
145	    const pickerOpts: OpenFilePickerOptions = {
146	      types: [
147	        {
148	          description: "json",
149	          accept: { "application/json": [".json"] },
150	        },
151	      ],
152	      multiple: false,
153	    };
154	
155	    const [fileHandle] = await window.showOpenFilePicker(pickerOpts) as Array<FileSystemFileHandle>;
156	    const file = await fileHandle.getFile();
157	    const content = await file.text();
158	
159	    let mapStyle;
160	    try {
161	      mapStyle = JSON.parse(content);
162	    } catch (err) {
163	      this.setState({
164	        error: (err as Error).toString()
165	      });
166	      return;
167	    }
168	    mapStyle = style.ensureStyleValidity(mapStyle);
169	
170	    this.props.onStyleOpen(mapStyle, fileHandle);
171	    this.onOpenToggle();
172	    return file;
173	  };
174	
175	  // it is not guaranteed that the File System Access API is available on all
176	  // browsers. If the function is not available, a fallback behavior is used.
177	  onFileChanged = (files: FileList | null) => {
178	    if (!files) return;
179	    if (files.length === 0) return;
180	    const file = files[0];
181	    const reader = new FileReader();
182	    this.clearError();
183	
184	    reader.readAsText(file, "UTF-8");
185	    reader.onload = e => {
186	      let mapStyle;
187	      try {
188	        mapStyle = JSON.parse(e.target?.result as string);
189	      }
190	      catch (err) {
191	        this.setState({
192	          error: (err as Error).toString()
193	        });
194	        return;
195	      }
196	      mapStyle = style.ensureStyleValidity(mapStyle);
197	      this.props.onStyleOpen(mapStyle);
198	      this.onOpenToggle();
199	    };
200	    reader.onerror = e => console.log(e.target);
201	  };
202	
203	  onOpenToggle() {
204	    this.setState({
205	      styleUrl: "",
206	      isDragOver: false,
207	    });
208	    this.clearError();
209	    this.props.onOpenToggle();
210	  }
211	
212	  onBrowseClick = async () => {
213	    if (typeof window.showOpenFilePicker === "function") {
214	      await this.onOpenFile();
215	      return;
216	    }
217	
218	    this.fileInputRef.current?.click();
219	  };
220	
221	  onFileDragOver = (e: DragEvent<HTMLDivElement>) => {
222	    e.preventDefault();
223	    e.stopPropagation();
224	
225	    if (!this.state.isDragOver) {
226	      this.setState({ isDragOver: true });
227	    }
228	  };
229	
230	  onFileDragLeave = (e: DragEvent<HTMLDivElement>) => {
231	    e.preventDefault();
232	    e.stopPropagation();
233	    this.setState({ isDragOver: false });
234	  };
235	
236	  onFileDrop = (e: DragEvent<HTMLDivElement>) => {
237	    e.preventDefault();
238	    e.stopPropagation();
239	
240	    this.setState({ isDragOver: false });
241	    this.onFileChanged(e.dataTransfer.files);
242	  };
243	
244	  onChangeUrl = (url: string) => {
245	    this.setState({
246	      styleUrl: url,
247	    });
248	  };
249	
250	  render() {
251	    const t = this.props.t;
252	    const styleOptions = publicStyles.map(style => {
253	      return <PublicStyle
254	        key={style.id}
255	        url={style.url}
256	        title={style.title}
257	        thumbnailUrl={style.thumbnail}
258	        onSelect={this.onStyleSelect}
259	      />;
260	    });
261	
262	    let errorElement;
263	    if (this.state.error) {
264	      errorElement = (
265	        <div className="maputnik-modal-error">
266	          {this.state.error}
267	          <a href="#" onClick={() => this.clearError()} className="maputnik-modal-error-close">×</a>
268	        </div>
269	      );
270	    }
271	
272	    return (
273	      <div>
274	        <Modal
275	          data-wd-key="modal:open"
276	          isOpen={this.props.isOpen}
277	          onOpenToggle={() => this.onOpenToggle()}
278	          title={t("Open Style")}
279	        >
280	          {errorElement}
281	          <section className="maputnik-modal-section">
282	            <h1>{t("Open local Style")}</h1>
283	            <p>{t("Open a local JSON style from your computer.")}</p>
284	            <div
285	              data-wd-key="modal:open.dropzone"
286	              className={`maputnik-upload-dropzone${this.state.isDragOver ? " maputnik-upload-dropzone--active" : ""}`}
287	              role="button"
288	              tabIndex={0}
289	              onDragOver={this.onFileDragOver}
290	              onDragLeave={this.onFileDragLeave}
291	              onDrop={this.onFileDrop}
292	              onClick={() => void this.onBrowseClick()}
293	              onKeyDown={(e) => {
294	                if (e.key === "Enter" || e.key === " ") {
295	                  e.preventDefault();
296	                  void this.onBrowseClick();
297	                }
298	              }}
299	            >
300	              <div className="maputnik-upload-dropzone-content">
301	                <MdFileUpload className="maputnik-upload-dropzone-icon" aria-hidden="true" />
302	                <p className="maputnik-upload-dropzone-text">
303	                  {t("Drag and drop a style JSON file here or click to browse")}
304	                </p>
305	              </div>
306	              <input
307	                ref={this.fileInputRef}
308	                data-wd-key="modal:open.file.input"
309	                type="file"
310	                style={{ display: "none" }}
311	                onChange={(e) => this.onFileChanged(e.target.files)}
312	              />
313	            </div>
314	          </section>
315	
316	          <section className="maputnik-modal-section">
317	            <form onSubmit={this.onSubmitUrl}>
318	              <h1>{t("Load from URL")}</h1>
319	              <p>
320	                <Trans t={t}>
321	                  Load from a URL. Note that the URL must have <a href="https://enable-cors.org" target="_blank" rel="noopener noreferrer">CORS enabled</a>.
322	                </Trans>
323	              </p>
324	              <InputUrl
325	                aria-label={t("Style URL")}
326	                data-wd-key="modal:open.url.input"
327	                type="text"
328	                className="maputnik-input"
329	                default={t("Enter URL...")}
330	                value={this.state.styleUrl}
331	                onInput={this.onChangeUrl}
332	                onChange={this.onChangeUrl}
333	              />
334	              <div>
335	                <InputButton
336	                  data-wd-key="modal:open.url.button"
337	                  type="submit"
338	                  className="maputnik-big-button"
339	                  disabled={this.state.styleUrl.length < 1}
340	                >Load from URL</InputButton>
341	              </div>
342	            </form>
343	          </section>
344	
345	          <section className="maputnik-modal-section maputnik-modal-section--shrink">
346	            <h1>{t("Gallery Styles")}</h1>
347	            <p>
348	              {t("Open one of the publicly available styles to start from.")}
349	            </p>
350	            <div className="maputnik-style-gallery-container">
351	              {styleOptions}
352	            </div>
353	          </section>
354	        </Modal>
355	
356	        <ModalLoading
357	          isOpen={!!this.state.activeRequest}
358	          title={t("Loading style")}
359	          onCancel={(e: Event) => this.onCancelActiveRequest(e)}
360	          message={t("Loading") + ": " + this.state.activeRequestUrl}
361	        />
362	      </div>
363	    );
364	  }
365	}
