310	      />;
311	    });
312	
313	    return <Modal
314	      data-wd-key="modal:sources"
315	      isOpen={this.props.isOpen}
316	      onOpenToggle={this.props.onOpenToggle}
317	      title={t("Sources")}
318	    >
319	      <section className="maputnik-modal-section">
320	        <h1>{t("Active Sources")}</h1>
321	        {activeSources}
322	      </section>
323	
324	      <section className="maputnik-modal-section">
325	        <h1>{t("Choose Public Source")}</h1>
326	        <p>
327	          {t("Add one of the publicly available sources to your style.")}
328	        </p>
329	        <div className="maputnik-public-sources" style={{maxWidth: 500}}>
330	          {tilesetOptions}
331	        </div>
332	      </section>
333	
334	      <section className="maputnik-modal-section">
335	        <h1>{t("Add New Source")}</h1>
336	        <p>{t("Add a new source to your style. You can only choose the source type and id at creation time!")}</p>
337	        <AddSource
338	          onAdd={(sourceId: string, source: SourceSpecification) => this.props.onStyleChanged(addSource(mapStyle, sourceId, source))}
339	          {...i18nProps}
340	        />
341	      </section>
342	    </Modal>;
343	  }
344	}
345	
346	const ModalSources = withTranslation()(ModalSourcesInternal);
347	export default ModalSources;
