8	
9	function displayValue(value: string | number | Date | object | undefined) {
10	  if (typeof value === "undefined" || value === null) return value;
11	  if (value instanceof Date) return value.toLocaleString();
12	  if (typeof value === "object" ||
13	          typeof value === "number" ||
14	          typeof value === "string") return value.toString();
15	  return value;
16	}
17	
18	function renderKeyValueTableRow(key: string, value: string | undefined) {
19	  return <tr key={key}>
20	    <td className="maputnik-popup-table-cell">{key}</td>
21	    <td className="maputnik-popup-table-cell">{value}</td>
22	  </tr>;
23	}
24	
25	function renderFeature(feature: InspectFeature, idx: number) {
26	  return <React.Fragment key={idx}>
27	    <tr>
28	      <td colSpan={2} className="maputnik-popup-layer-id">{feature.layer["source"]}: {feature.layer["source-layer"]}{feature.inspectModeCounter && <span> × {feature.inspectModeCounter}</span>}</td>
29	    </tr>
30	    {renderKeyValueTableRow("$type", feature.geometry.type)}
31	    {renderKeyValueTableRow("$id", displayValue(feature.id))}
32	    {Object.keys(feature.properties).map(propertyName => {
33	      const property = feature.properties[propertyName];
34	      return renderKeyValueTableRow(propertyName, displayValue(property));
35	    })}
36	  </React.Fragment>;
37	}
